__NUXT_JSONP__("/finanzas-publicas/noticias/se_debe_mejorar_la_eficiencia_y_transparencia_del_gasto_publico_advierte_ethos", (function(a,b,c,d,e){return {data:[{post:{slug:"se_debe_mejorar_la_eficiencia_y_transparencia_del_gasto_publico_advierte_ethos",title:"Se debe mejorar la eficiencia y transparencia del gasto público, advierte Ethos",date:"2025-05-27T22:00:56.337Z",img:"https:\u002F\u002Fucarecdn.com\u002Ff4d563ee-2f16-40da-881f-7a3bab5e9130\u002F","img-alt":"Gasto público",autor:"Belén Saldívar, El Economista",link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Feconomia\u002Fdebe-mejorar-eficiencia-transparencia-gasto-publico-advierte-ethos-20250525-760696.html",category:"finanzas-publicas",extracto:"El año pasado el gasto ejercido por el gobierno fue de 9.2 billones de pesos, lo que resultó 1.5% mayor a lo aprobado.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Tras el sobre ejercicio del gasto público que se reportó el año pasado, la organización civil Ethos Innovación en Políticas Públicas señaló que se debe mejorar la eficiencia y la transparencia del ejercicio de los recursos públicos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En un análisis de la Cuenta Pública 2024, la organización civil destacó que el año pasado se dio prioridad a rubros como energía y combustibles, mientras que en sectores fundamentales para la población mexicana, como salud y educación incluso se observaron recortes."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“En un contexto de múltiples prioridades y recursos limitados, resulta fundamental no solo enfocarse en cuánto se gasta, sino también en cómo se gasta. Mejorar la eficiencia y la transparencia en el ejercicio del gasto público se presenta como un elemento crucial para maximizar el impacto de los recursos disponibles. Esto implica optimizar los procesos de asignación y ejecución del gasto, fortalecer los mecanismos de rendición de cuentas y garantizar que los recursos se utilicen de manera efectiva para alcanzar los objetivos planteados\", destacó el think tank."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"De acuerdo con los datos de la Secretaría de Hacienda y Crédito Público (SHCP), el año pasado el gasto ejercido por el gobierno fue de 9.2 billones de pesos, lo que resultó 1.5% mayor a lo aprobado."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El sobrejercicio reportado fue equivalente a 139,392 millones de pesos, lo cual se debió a un mayor gasto programable en 4.3%, mientras que el no programable resultó en 5.3% menor."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“La asignación del gasto público refleja claramente las prioridades gubernamentales y permite identificar áreas de oportunidad. El notable incremento en el gasto destinado a combustible y energía contrasta de manera alarmante con los aumentos marginales observados en sectores fundamentales como educación o incluso en recorte como salud”, consignó el análisis."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Los números mostraron que el año pasado se destinaron 1.3 billones de pesos al rubro de energía y combustibles, lo que representó un sobre ejercicio de 15 por ciento. Sin embargo, en rubros como educación y salud, que son prioritarios para la sociedad y en donde históricamente se ha gastado poco, la historia fue diferente."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En el caso del rubro de educación, la Cuenta Pública 2024 mostró que se gastó un billón de pesos, apenas 1% más de lo aprobado, mientras que en salud se ejercieron 935,000 millones de pesos, lo que representó un subejercicio de 2.8 por ciento."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Esta tendencia representa un riesgo significativo para el desarrollo social de la población. Invertir en el bienestar social y en el capital humano es esencial para construir una base sólida para el futuro”, indicó la organización."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El año pasado, el último del gobierno de Andrés Manuel López Obrador, se priorizó a los proyectos y obras insignia de la administración, lo cual llevó no sólo a que absorbieran mayores recursos del presupuesto, sino también un mayor endeudamiento."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"De esta manera, los Requerimientos Financieros del Sector Público (RFSP) lograron un nivel récord de 5.7% del PIB, el cual se busca reducir este año a 3.9 por ciento."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:b,tag:"strong",props:{},children:[{type:a,value:"Ingresos crecen, pero no son suficientes"}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Del lado de los ingresos públicos, Ethos señaló que el año pasado estos lograron crecer en un entorno difícil, donde se vio un enfriamiento de la economía mexicana hacia la segunda mitad del año, el cual parece haberse extendido hacia este año."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Pese a este incremento, la organización civil destacó la importancia de potenciar estos recursos, sobre todo ante las crecientes presiones del gasto público, así como las necesidades que existen por aumentar recursos en rubros prioritarios."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“El análisis de la Cuenta Pública 2024 revela una realidad compleja para la economía mexicana. Si bien es cierto que los ingresos presupuestarios experimentaron un crecimiento en términos absolutos, este incremento no logra satisfacer las crecientes necesidades de gasto del país. Desafortunadamente esta insuficiencia ha obligado al gobierno a recurrir a un mayor endeudamiento”, mencionó la organización."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En el 2024, el gobierno logró tener ingresos por 7.5 billones de pesos, lo que representó un crecimiento anual de 1.4%, además de ser 2.2% por arriba de lo aprobado por el Congreso. El aumento, de acuerdo con lo analizado, se debió a una mayor recaudación de los ingresos no tributarios y de los organismos y empresas del estado."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En este sentido, los ingresos no tributarios se ubicaron 110,380 millones de pesos por encima de lo aprobado (42.2%), por un aumento en los ingresos por derechos, productos y aprovechamientos. En cuanto a los organismos y empresas, sus ingresos adicionales fueron 130,925 millones de pesos (12.1%), principalmente debido a mayores ingresos de la CFE por mayores ingresos por ventas de energía, explicó Ethos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“En contraste, los ingresos petroleros se observaron por debajo de lo aprobado y de lo recaudado en el 2023. La recaudación de este tipo de ingresos se ubicó en 958,914 millones de pesos, 8.5% menos de lo aprobado. Lo anterior se debe a una menor producción de hidrocarburos que no fue compensada por un mayor precio del petróleo, menor precio del gas natural y depreciación del tipo de cambio. Además, estos ingresos presentaron una caída anual de 15.3%”, añadió."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fse_debe_mejorar_la_eficiencia_y_transparencia_del_gasto_publico_advierte_ethos",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2025-11-25T01:24:03.272Z")));